chain=ids('ChainProperties',{'getChainedTo'})[0];dread=ids('EntityDreadMob',{'readAdditionalSaveData'})[0]
a=accepted(chain,'icefire-paid-chain-attachment-uuid-vs-runtime-id-rebind-and-return-boundary','完整ChainProperties/ItemChain/EntityChainTie及ServerEvents四完整事件；付费绑链→UUID复查→真实牵引/解绑返物','Citadel compound中的ChainDataIaf compoundlist，每连接保存ChainOwnerIaf UUID和运行时ChainOwnerIDIaf；Tie持久TileXYZ','server以UUID重新找同维目标并更新缓存entityID；client先缓存ID，找不到才按UUID查在线player；超过7距离tick实际施加拉力','这是已消耗chain物品对应的具体附着关系载荷，不是单纯owner getter。实体链可重新绑定玩家→Tie或另一活体；拆Tie和死亡返普通chain物品，完整item手势/重复绑定guard/收费和真实事件消费已读。EntityChainTie坐标保存只是同owner支持，不按每端点或sticky版本再计。','Citadel外部实体NBT真实磁盘hook源码未取得，明确只研究mod侧载荷reader/ID fallback/生命周期，不宣称已核持久存盘或跨重生。Client非空旧entityID不核UUID可能误指；server未载入目标不删除原UUID，getUUID缺坏格式无catch；死亡返物仅已解析目标数量后清全list，未载入连接可能丢付费链。Tie.remove不区分卸载/死亡等reason且不检查side会尝试清链/返物，是静态风险未运行。sticky清链不退款；spawn不检失败。不得直接拷该临时连接到玩家永久Clone。',ids('ChainProperties',{'attachChain','removeChain','tickChain','clearChainData'})+ids('ItemChain',{'interactLivingEntity','attachToFence'})+ids('EntityChainTie',{'readAdditionalSaveData','addAdditionalSaveData','remove','interact'})+ids('ServerEvents',{'onEntityDie','onEntityUpdate','onEntityInteract','onPlayerStartTracking'}))
b=accepted(dread,'icefire-dread-command-identity-legacy-name-and-summon-budget-continuity','完整DreadMob/DreadLich；读旧CommanderUUID String或现代UUID→实际Lich投召唤物/目标继承/MinionCount额度','CommanderUUID现代UUID或旧name，Lich独立MinionCount Int已召唤额度/Variant；fire和minion相对冷却未保存','旧名字交OldUsersConverter；恢复commander控制实体，Lich loaded count<5才可继续召唤，恢复持装备后setCombatTask重建AI','同一军团关系/计数整体1；真实performRangedAttack创建minion并写commander UUID，DreadMob.aiStep从同维在线lich继承目标。MinionCount不同于通用tame宠物owner且有真实数量限制消费者；非按各亡灵型号/UUID字段拆。读失败只catch setCommanderId，不覆盖前置OldUsersConverter调用。','不声称完整成功：remove对所有RemovalReason包括卸载尝试减count，不按死亡过滤，可破坏磁盘额度一致性；生成boolean忽略仍count++，无重算，负count无夹紧。necromancyEntity全方法已读，传装备同引用未清原槽；onKillEntity仓库仅声明无调用，不宣称已打通真实击杀转化。DreadHorse非DreadMob分支不会被写CommanderId，非全物种承诺。旧名解析底层未本轮再读/运行，getCommander未找到不清UUID；相对冷却是瞬态不复制到Dynasty白名单。',ids('EntityDreadMob',{'addAdditionalSaveData','getCommander','aiStep','remove','onKillEntity','necromancyEntity'})+ids('EntityDreadLich',{'readAdditionalSaveData','addAdditionalSaveData','performRangedAttack','aiStep'}))
record(200,[a])
p=O/'reviews/batch-068.json';old=json.loads(p.read_text());before=next(r for r in old if r['candidate_id']==dread)
assert before['status'] in ('duplicate','accepted')
